SELECT MIN(L.TITULO) NOME, MAX(NULLIF(L.AUTOR, '')) AUTOR, MAX(L.TRECHO) TRECHO, COUNT(*) N FROM LIVROS_INDICADOS L LEFT JOIN LIVROS_NOMES N ON N.NOME = L.TITULO COLLATE utf8mb4_0900_ai_ci WHERE N.ID IS NULL GROUP BY L.TITULO COLLATE utf8mb4_0900_ai_ci HAVING MAX(NULLIF(L.AUTOR, '')) IS NOT NULL OR MAX(L.TRECHO LIKE '%livro%') = 1 OR COUNT(DISTINCT L.VIDEO_ID) >= 2 ORDER BY (MAX(NULLIF(L.AUTOR, '')) IS NOT NULL AND MAX(L.TRECHO LIKE '%livro%') = 1) DESC, (MAX(NULLIF(L.AUTOR, '')) IS NOT NULL) DESC, N DESC LIMIT {{limit}}